using System.RateLimiting;
using Microsoft.AspNetCore.RateLimiting;

builder.Services.AddRateLimiter(options =>
{
    options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;

    options.AddSlidingWindowLimiter("api", limiterOptions =>
    {
        limiterOptions.PermitLimit = 100;              // requests allowed
        limiterOptions.Window = TimeSpan.FromMinutes(1);
        limiterOptions.SegmentsPerWindow = 6;          // 10-second segments
        limiterOptions.QueueLimit = 0;                 // no queueing — reject fast
        limiterOptions.QueueProcessingOrder = QueueProcessingOrder.OldestFirst;
    });

    // Partition: authenticated user, else IP
    options.OnRejected = async (context, cancellationToken) =>
    {
        context.HttpContext.Response.Headers.RetryAfter = "30";
        await context.HttpContext.Response.WriteAsync(
            "{\"error\":\"rate_limit_exceeded\",\"retryAfter\":30}",
            cancellationToken);
    };
});

var app = builder.Build();
app.UseRateLimiter();                 // after UseRouting, before endpoints

// Global default, tighter bucket on the expensive endpoint
[EnableRateLimiting("api")]
[HttpPost("reports/generate")]
public IActionResult Generate() => Accepted();

[DisableRateLimiting]                 // health checks should never 429
[HttpGet("health")]
public IActionResult Health() => Ok();
